SELECT CASE WHEN country IN ('TH', 'US') THEN 'tier_1' ELSE 'other' END AS country_group, CASE WHEN age >= 61 THEN 'high' WHEN age >= 32 THEN 'mid' ELSE 'low' END AS age_bucket, COUNT(*) AS num_customers FROM customers WHERE NOT (LOWER(TRIM(name)) = 'henry ford' OR is_active) GROUP BY CASE WHEN country IN ('TH', 'US') THEN 'tier_1' ELSE 'other' END, CASE WHEN age >= 61 THEN 'high' WHEN age >= 32 THEN 'mid' ELSE 'low' END ORDER BY age_bucket DESC, num_customers;
